                {
                    "window": name,
                    "scenario": scenario,
                    "valid": valid,
                    "count": count,
                    "transitions": transitions,
                    "stability": stability,
                    "trend": trend,
                }
            )

    return {
        "schema": _GRADE_WINDOWS_SCHEMA,
        "windows": out_windows,
        "scenarios": list(scenarios),
        "data": rows,
